module fixed_point_adder #(
    parameter Q = 15,
    parameter N = 32
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] res;

    always @(*) begin
        if (a[N-1] == b[N-1]) begin

            res = a + b;
        end else begin

            if (a >= b) begin
                res = a - b;
            end else begin
                res = b - a;
            end
        end
    end

    assign c = res;

endmodule
